def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find the compact multi-cell object, excluding the scattered single-cell
    # markers, then replicate it around each marker.
    pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    comps = []
    while pts:
        start = pts.pop()
        comp = {start}
        q = [start]
        while q:
            r, c = q.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in pts:
                    pts.remove(p)
                    comp.add(p)
                    q.append(p)
        comps.append(comp)

    motif = max(comps, key=len)
    # The anchor is the repeated marker color within the motif: use the
    # central cell of its bounding box as the alignment point.
    rmin = min(r for r,c in motif)
    rmax = max(r for r,c in motif)
    cmin = min(c for r,c in motif)
    cmax = max(c for r,c in motif)
    ar, ac = (rmin+rmax)//2, (cmin+cmax)//2
    shape = [(r-ar, c-ac, grid[r][c]) for r,c in motif]

    marker_color = min((grid[r][c] for r in range(h) for c in range(w)
                        if grid[r][c] != bg and (r,c) not in motif),
                       default=None)
    if marker_color is None:
        return out

    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker_color and (r,c) not in motif:
                for dr, dc, v in shape:
                    y, x = r+dr, c+dc
                    if 0 <= y < h and 0 <= x < w:
                        out[y][x] = v
    return out
